/// Node example: parse - Anthropic parse extracts content, model, tokens from REST response
/// 
/// Tests that node 'parse' produces expected outputs for given inputs.
#[test]
fn test_example_parse_anthropic_parse_extracts_content_model_tokens_from_rest_response() {
    let dag = crate::graph::build_chat_completion_graph();
    let mut inputs = std::collections::HashMap::new();
    inputs.insert("provider".to_string(), Value::Str("anthropic".to_string()));
    inputs.insert("response".to_string(), Value::Response(gunbc_ir::transport::TransportResponse::Rest(gunbc_ir::transport::RestResponse { status: 200, body: serde_json::json!({"content":[{"text":"Anthropic test response.","type":"text"}],"id":"msg_mock_test","model":"claude-sonnet-4-20250514","role":"assistant","stop_reason":"end_turn","type":"message","usage":{"input_tokens":10,"output_tokens":20}}), headers: std::collections::HashMap::new() })));
    let outputs = gunbc_exec::execute_single_node(&dag, "parse", inputs, gunbc_exec::ExecutionMode::Real).expect("node 'parse' should execute successfully");

    // Check output port 'content'
    let output_content = outputs.get("content").expect("output port 'content' should exist");
    assert_eq!(*output_content, Value::Str("Anthropic test response.".to_string()), "expected exact value");
    // Check output port 'finish_reason'
    let output_finish_reason = outputs.get("finish_reason").expect("output port 'finish_reason' should exist");
    assert_eq!(*output_finish_reason, Value::Str("Stop".to_string()), "expected exact value");
    // Check output port 'input_tokens'
    let output_input_tokens = outputs.get("input_tokens").expect("output port 'input_tokens' should exist");
    assert_eq!(*output_input_tokens, Value::Int(10), "expected exact value");
    // Check output port 'model'
    let output_model = outputs.get("model").expect("output port 'model' should exist");
    assert_eq!(*output_model, Value::Str("claude-sonnet-4-20250514".to_string()), "expected exact value");
    // Check output port 'output_tokens'
    let output_output_tokens = outputs.get("output_tokens").expect("output port 'output_tokens' should exist");
    assert_eq!(*output_output_tokens, Value::Int(20), "expected exact value");
}

